<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { RefreshCw, X } from 'lucide-vue-next'
import { supabase } from '../lib/supabase'
import { listAdminCancellations, listAdminRefunds, resolveRefund } from '../services/refundService'
import '../assets/refunds.css'

const tab = ref('cancelaciones'); const cancellations = ref([]); const refunds = ref([]); const loading = ref(true); const error = ref(''); const notice = ref(''); const selected = ref(null); const resolving = ref(false); const search = ref(''); const reason = ref(''); const origin = ref(''); const refundStatus = ref(''); const refundType = ref(''); let channel
const reasonLabels = { SIN_REPARTIDORES_EN_AREA: 'Sin repartidores en el área', RESTAURANTE_RECHAZA: 'Restaurante rechazó', PRODUCTOS_NO_DISPONIBLES: 'Productos no disponibles', PROBLEMAS_DE_ENTREGA: 'Problemas de entrega', SOLICITUD_CLIENTE: 'Solicitud del cliente', CAMBIO_DE_OPINION: 'Cambio de opinión', ERROR_EN_PEDIDO: 'Error en el pedido', DIRECCION_INCORRECTA: 'Dirección incorrecta', DEMORA_EN_PEDIDO: 'Demora en el pedido', OTRO: 'Otro' }
const originLabels = { ADMIN: 'Administrador', CLIENTE: 'Cliente', SISTEMA: 'Sistema', REPARTIDOR: 'Repartidor' }
const statusLabels = { SIMULADO_PENDIENTE: 'Reembolso pendiente', SIMULADO_COMPLETADO: 'Reembolso completado', REVISION_MANUAL: 'Revisión manual pendiente', REVISION_APROBADA: 'Aprobación registrada', REVISION_RECHAZADA: 'Reembolso rechazado' }
const filteredCancellations = computed(() => cancellations.value.filter((item) => { const order = item.pedidos || {}; const text = `${order.numero || ''} ${order.perfiles?.nombre || ''} ${order.restaurantes?.nombre || ''}`.toLowerCase(); return (!search.value || text.includes(search.value.toLowerCase())) && (!reason.value || item.motivo_codigo === reason.value) && (!origin.value || item.origen === origin.value) }))
const filteredRefunds = computed(() => refunds.value.filter((item) => (!refundStatus.value || item.estado === refundStatus.value) && (!refundType.value || (refundType.value === 'AUTOMATICO' ? item.automatico : !item.automatico))))
const kpis = computed(() => ({ pending: refunds.value.filter((item) => item.estado === 'REVISION_MANUAL').length, automatic: refunds.value.filter((item) => item.automatico).length, completed: refunds.value.filter((item) => item.estado === 'SIMULADO_COMPLETADO').length, total: refunds.value.filter((item) => item.estado === 'SIMULADO_COMPLETADO').reduce((sum, item) => sum + Number(item.monto || 0), 0) }))
function reasonLabel(value) { return reasonLabels[value] || value || '—' }; function statusLabel(value) { return statusLabels[value] || value }; function money(value) { return `$${Number(value || 0).toFixed(2)}` }; function date(value) { return value ? new Date(value).toLocaleString('es-SV') : '—' }
async function load() { loading.value = true; error.value = ''; try { [cancellations.value, refunds.value] = await Promise.all([listAdminCancellations(), listAdminRefunds()]) } catch (e) { error.value = e.message || 'No se pudo cargar la gestión de reembolsos.' } finally { loading.value = false } }
async function resolve(approve) { if (!selected.value || selected.value.estado !== 'REVISION_MANUAL') return; if (!window.confirm(approve ? '¿Confirmas aprobar esta devolución?' : '¿Confirmas rechazar esta devolución?')) return; resolving.value = true; try { await resolveRefund(selected.value.id, approve); notice.value = approve ? 'Aprobación registrada. La devolución aún no se considera dinero devuelto.' : 'Reembolso rechazado.'; selected.value = null; await load() } catch (e) { error.value = e.message?.includes('REEMBOLSO_NO_DISPONIBLE') ? 'El reembolso ya fue procesado.' : e.message || 'No se pudo resolver el reembolso.' } finally { resolving.value = false } }
function subscribe() { channel = supabase.channel('admin-refunds').on('postgres_changes', { event: '*', schema: 'public', table: 'cancelaciones' }, load).on('postgres_changes', { event: '*', schema: 'public', table: 'reembolsos' }, load).subscribe() }
onMounted(async () => { await load(); subscribe() }); onBeforeUnmount(() => channel && supabase.removeChannel(channel))
</script>
<template><section class="admin-view"><div class="admin-view-heading"><div><span class="admin-eyebrow">CONTROL FINANCIERO</span><h2>Cancelaciones y reembolsos</h2><p>Las devoluciones no procesan pagos bancarios.</p></div><button class="admin-icon-button" @click="load"><RefreshCw :size="18" /></button></div><div class="refund-tabs"><button :class="{ active: tab === 'cancelaciones' }" @click="tab = 'cancelaciones'">Cancelaciones</button><button :class="{ active: tab === 'reembolsos' }" @click="tab = 'reembolsos'">Reembolsos</button></div><p v-if="error" class="admin-alert">{{ error }}</p><p v-if="notice" class="admin-success">{{ notice }}</p><div v-if="loading" class="admin-empty">Cargando información…</div><template v-else-if="tab === 'cancelaciones'"><div class="refund-filters"><input v-model="search" placeholder="Buscar pedido, cliente o restaurante" /><select v-model="reason"><option value="">Todos los motivos</option><option v-for="(label, code) in reasonLabels" :key="code" :value="code">{{ label }}</option></select><select v-model="origin"><option value="">Todos los orígenes</option><option value="CLIENTE">Cliente</option><option value="ADMIN">Administrador</option><option value="SISTEMA">Sistema</option><option value="REPARTIDOR">Repartidor</option></select></div><div v-if="!filteredCancellations.length" class="admin-empty">No hay cancelaciones con esos filtros.</div><div v-else class="admin-panel admin-table-wrap"><table class="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Restaurante</th><th>Motivo</th><th>Origen</th><th>Actor</th><th>Pago</th><th>Reembolso</th><th>Fecha</th></tr></thead><tbody><tr v-for="item in filteredCancellations" :key="item.id" @click="selected = item.pedidos?.reembolsos?.[0] || item"><td>#{{ item.pedidos?.numero }}</td><td>{{ item.pedidos?.perfiles?.nombre || '—' }}</td><td>{{ item.pedidos?.restaurantes?.nombre || '—' }}</td><td>{{ reasonLabel(item.motivo_codigo) }}<small>{{ item.descripcion || 'Sin descripción' }}</small></td><td>{{ originLabels[item.origen] || item.origen }}</td><td>{{ item.actor?.nombre || (item.origen === 'SISTEMA' ? 'Sistema' : '—') }}</td><td>{{ item.pedidos?.metodo_pago === 'TARJETA_SIMULADA' ? 'Tarjeta' : 'Efectivo' }} · {{ item.pedidos?.estado_pago }}</td><td>{{ item.pedidos?.reembolsos?.[0] ? statusLabel(item.pedidos.reembolsos[0].estado) : 'Sin devolución' }}</td><td>{{ date(item.created_at) }}</td></tr></tbody></table></div></template><template v-else><div class="refund-kpis"><article class="refund-kpi"><span>Pendientes de revisión</span><strong>{{ kpis.pending }}</strong></article><article class="refund-kpi"><span>Reembolsos automáticos</span><strong>{{ kpis.automatic }}</strong></article><article class="refund-kpi"><span>Completados</span><strong>{{ kpis.completed }}</strong></article><article class="refund-kpi"><span>Total efectivamente reembolsado</span><strong>{{ money(kpis.total) }}</strong></article></div><div class="refund-filters"><select v-model="refundStatus"><option value="">Todos los estados</option><option v-for="(label, code) in statusLabels" :key="code" :value="code">{{ label }}</option></select><select v-model="refundType"><option value="">Automáticos y manuales</option><option value="AUTOMATICO">Automáticos</option><option value="MANUAL">Manuales</option></select></div><div v-if="!filteredRefunds.length" class="admin-empty">No hay reembolsos con esos filtros.</div><div v-else class="admin-panel admin-table-wrap"><table class="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Motivo</th><th>Monto</th><th>Tipo</th><th>Estado</th><th>Solicitud</th><th>Resolución</th></tr></thead><tbody><tr v-for="item in filteredRefunds" :key="item.id" @click="selected = item"><td>#{{ item.pedidos?.numero }}</td><td>{{ item.pedidos?.perfiles?.nombre || '—' }}</td><td>{{ reasonLabel(item.motivo_codigo) }}</td><td>{{ money(item.monto) }}</td><td>{{ item.automatico ? 'Automático' : 'Manual' }}</td><td><span class="refund-pill" :class="{ 'refund-pill--success': item.estado === 'SIMULADO_COMPLETADO', 'refund-pill--warning': item.estado === 'REVISION_MANUAL', 'refund-pill--danger': item.estado === 'REVISION_RECHAZADA' }">{{ statusLabel(item.estado) }}</span></td><td>{{ date(item.created_at) }}</td><td>{{ item.estado === 'REVISION_MANUAL' ? 'Pendiente' : date(item.updated_at) }}</td></tr></tbody></table></div></template><div v-if="selected && selected.pedidos" class="admin-drawer-backdrop" @click.self="selected = null"><aside class="admin-order-drawer"><button class="admin-drawer-close" @click="selected = null"><X :size="20" /></button><span class="admin-eyebrow">{{ selected.pedidos?.numero ? `PEDIDO #${selected.pedidos.numero}` : 'REEMBOLSO' }}</span><h3>{{ selected.pedidos?.restaurantes?.nombre }}</h3><div class="refund-detail"><p>Cliente: <strong>{{ selected.pedidos?.perfiles?.nombre || '—' }}</strong></p><p>Motivo: <strong>{{ reasonLabel(selected.motivo_codigo) }}</strong></p><p v-if="selected.descripcion">Descripción: <strong>{{ selected.descripcion }}</strong></p><p v-if="selected.monto != null">Monto: <strong>{{ money(selected.monto) }}</strong></p><p v-if="selected.estado">Estado: <strong>{{ statusLabel(selected.estado) }}</strong></p><p v-if="selected.revisor?.nombre">Revisó: <strong>{{ selected.revisor.nombre }}</strong></p><p v-if="selected.estado === 'REVISION_MANUAL'">La devolución simulada requiere revisión administrativa.</p></div><div v-if="selected.estado === 'REVISION_MANUAL'" class="refund-modal-actions"><button class="approve" :disabled="resolving" @click="resolve(true)">Aprobar</button><button class="reject" :disabled="resolving" @click="resolve(false)">Rechazar</button><button class="close" :disabled="resolving" @click="selected = null">Cerrar</button></div></aside></div></section></template>
